public int LadderLength(string begin, string end, IList<string> wordList) {
    var words = new HashSet<string>(wordList);
    if (!words.Contains(end)) return 0;
    var queue = new Queue<string>();
    queue.Enqueue(begin);
    words.Remove(begin);
    for (int length = 1; queue.Count > 0; length++) {
        for (int k = queue.Count; k > 0; k--) {          // level = chain length
            var word = queue.Dequeue().ToCharArray();
            if (new string(word) == end) return length;
            for (int i = 0; i < word.Length; i++) {
                char original = word[i];
                for (char c = 'a'; c <= 'z'; c++) {
                    word[i] = c;
                    var next = new string(word);
                    if (words.Remove(next)) queue.Enqueue(next);
                }
                word[i] = original;
            }
        }
    }
    return 0;
}

