public int ShortestPath(int[][] grid, int k) {
    int rows = grid.Length, cols = grid[0].Length;
    if (rows == 1 && cols == 1) return 0;
    var seen = new bool[rows, cols, k + 1];      // a state: the cell and how many walls can still be broken
    var queue = new Queue<(int r, int c, int rem)>();
    queue.Enqueue((0, 0, k));
    seen[0, 0, k] = true;
    int[] dr = { -1, 0, 1, 0 }, dc = { 0, 1, 0, -1 };
    for (int steps = 1; queue.Count > 0; steps++) {
        for (int size = queue.Count; size > 0; size--) {     // one BFS level is one step
            var (r, c, rem) = queue.Dequeue();
            for (int d = 0; d < 4; d++) {
                int y = r + dr[d], x = c + dc[d];
                if (y < 0 || x < 0 || y >= rows || x >= cols) continue;
                int left = rem - grid[y][x];     // stepping on a wall spends a break
                if (left < 0 || seen[y, x, left]) continue;
                if (y == rows - 1 && x == cols - 1) return steps;
                seen[y, x, left] = true;
                queue.Enqueue((y, x, left));
            }
        }
    }
    return -1;
}

