public int SlidingPuzzle(int[][] board) {
    // 2×3 cells: 0 1 2 / 3 4 5; moves[i] — where the gap can go from i
    int[][] moves = { new[] { 1, 3 }, new[] { 0, 2, 4 }, new[] { 1, 5 },
                      new[] { 0, 4 }, new[] { 1, 3, 5 }, new[] { 2, 4 } };
    string start = string.Concat(board[0]) + string.Concat(board[1]), goal = "123450";
    var seen = new HashSet<string> { start };
    var queue = new Queue<string>();
    queue.Enqueue(start);
    for (int steps = 0; queue.Count > 0; steps++)
        for (int size = queue.Count; size > 0; size--) {
            string s = queue.Dequeue();
            if (s == goal) return steps;
            int z = s.IndexOf('0');
            foreach (int m in moves[z]) {
                var a = s.ToCharArray();
                (a[z], a[m]) = (a[m], a[z]);          // slide a tile into the gap
                var t = new string(a);
                if (seen.Add(t)) queue.Enqueue(t);
            }
        }
    return -1;
}

