public int LadderLength(string begin, string end, IList<string> wordList) {
    var words = new HashSet<string>(wordList);
    if (!words.Contains(end)) return 0;
    var front = new HashSet<string> { begin };
    var back = new HashSet<string> { end };
    words.Remove(begin); words.Remove(end);
    for (int length = 2; front.Count > 0 && back.Count > 0; length++) {
        if (front.Count > back.Count) (front, back) = (back, front);   // grow the smaller front
        var next = new HashSet<string>();
        foreach (var w in front) {
            var a = w.ToCharArray();
            for (int i = 0; i < a.Length; i++) {
                char orig = a[i];
                for (char ch = 'a'; ch <= 'z'; ch++) {
                    a[i] = ch;
                    var t = new string(a);
                    if (back.Contains(t)) return length;        // the fronts met
                    if (words.Remove(t)) next.Add(t);
                }
                a[i] = orig;
            }
        }
        front = next;
    }
    return 0;
}
